class KeyRotationManager:
    """
    Manages key rotation with bounded buffer.
    FVE INV-002: Maximum 1024 active secrets enforced via asyncio.Queue.
    """

    def __init__(self, max_secrets: int = CRA_PARAMS.max_active_secrets):
        self.max_secrets = max_secrets
        self._active_secrets: asyncio.Queue = asyncio.Queue(maxsize=max_secrets)
        self._rotation_count = 0
        self._failed_rotations = 0
        self._last_rotation_time = time.monotonic()
        self._circuit_broken = False

    async def add_secret(self, secret_id: str, secret_data: bytes, ttl: float = CRA_PARAMS.key_rotation_ttl_seconds) -> bool:
        """
        Add a new secret to the rotation buffer.
        Returns True if added, False if buffer full or circuit broken.
        """
        if self._circuit_broken:
            logger.warning("Circuit breaker active, rejecting secret addition")
            return False

        if self._active_secrets.qsize() >= self.max_secrets:
            # FVE INV-002: Reject if buffer full
            logger.warning(f"Secret buffer full ({self.max_secrets}), rejecting {secret_id}")
            self._failed_rotations += 1
            self._check_circuit_breaker()
            return False

        secret_entry = {
            "id": secret_id,
            "data": secret_data,
            "created_at": time.monotonic(),
            "ttl": ttl,
            "rotation_number": self._rotation_count
        }

        await self._active_secrets.put(secret_entry)
        self._rotation_count += 1
        logger.debug(f"Secret {secret_id} added (rotation #{self._rotation_count})")
        return True

    async def rotate_expired(self) -> int:
        """
        Remove expired secrets from buffer.
        Returns count of rotated secrets.
        """
        rotated = 0
        now = time.monotonic()
        temp_queue: asyncio.Queue = asyncio.Queue(maxsize=self.max_secrets)

        while not self._active_secrets.empty():
            secret = await self._active_secrets.get()
            age = now - secret["created_at"]
            
            if age >= secret["ttl"]:
                # FVE INV-001: Zeroize expired secret data
                secret["data"] = b'\x00' * len(secret["data"])
                rotated += 1
                logger.debug(f"Secret {secret['id']} rotated (age={age:.2f}s)")
            else:
                await temp_queue.put(secret)

        # Restore non-expired secrets
        self._active_secrets = temp_queue
        self._last_rotation_time = now
        return rotated

    def _check_circuit_breaker(self) -> None:
        """Self-healing circuit breaker based on CRA consensus."""
        if self._failed_rotations >= CRA_PARAMS.self_healing_budget:
            self._circuit_broken = True
            logger.critical(f"Circuit breaker engaged: {self._failed_rotations} failed rotations")
            # Reset after cooldown (simplified; production would use exponential backoff)
            asyncio.get_event_loop().call_later(60.0, self._reset_circuit_breaker)

    def _reset_circuit_breaker(self) -> None:
        """Reset circuit breaker after cooldown period."""
        self._circuit_broken = False
        self._failed_rotations = 0
        logger.info("Circuit breaker reset after cooldown")

    def get_stats(self) -> Dict[str, Any]:
        """Return rotation manager statistics."""
        return {
            "active_secrets": self._active_secrets.qsize(),
            "max_secrets": self.max_secrets,
            "total_rotations": self._rotation_count,
            "failed_rotations": self._failed_rotations,
            "circuit_broken": self._circuit_broken,
            "last_rotation": self._last_rotation_time
        }


