class EDSMATransactionType(Enum):
    KEY_ROTATION_POLICY = auto()
    CONSENSUS_PARAMETER_UPDATE = auto()
    CIRCUIT_BREAKER_RESET = auto()
    NODE_JOIN = auto()
    NODE_LEAVE = auto()


@dataclass
class EDSMATransaction:
    """Self-modification transaction for PBFT consensus."""
    transaction_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    transaction_type: EDSMATransactionType = EDSMATransactionType.KEY_ROTATION_POLICY
    payload: Dict[str, Any] = field(default_factory=dict)
    timestamp: float = field(default_factory=time.time)
    signature: Optional[bytes] = None
    node_id: str = field(default_factory=lambda: os.uname().nodename)

    def sign(self, private_key: bytes) -> None:
        """Sign transaction with HMAC-SHA256."""
        message = f"{self.transaction_id}{self.transaction_type.value}{json.dumps(self.payload, sort_keys=True)}{self.timestamp}".encode()
        self.signature = hmac.new(private_key, message, hashlib.sha256).digest()

    def verify(self, public_key: bytes) -> bool:
        """Verify transaction signature."""
        if not self.signature:
            return False
        message = f"{self.transaction_id}{self.transaction_type.value}{json.dumps(self.payload, sort_keys=True)}{self.timestamp}".encode()
        expected = hmac.new(public_key, message, hashlib.sha256).digest()
        return hmac.compare_digest(self.signature, expected)

    def to_json(self) -> str:
        """Serialize transaction to JSON for PBFT broadcast."""
        return json.dumps({
            "transaction_id": self.transaction_id,
            "transaction_type": self.transaction_type.name,
            "payload": self.payload,
            "timestamp": self.timestamp,
            "signature": self.signature.hex() if self.signature else None,
            "node_id": self.node_id
        })


