class QuantumKeyDistributionGateway:
    """
    Main gateway service orchestrating QKD operations.
    FVE INV-004: Guaranteed async socket cleanup on connection drop.
    """

    def __init__(self, host: str = "0.0.0.0", port: int = 8443):
        self.host = host
        self.port = port
        self._server: Optional[asyncio.AbstractServer] = None
        self._key_exchange = KyberKeyExchange()
        self._rotation_manager = KeyRotationManager()
        self._pbft_node = PBFTNode(node_id=os.uname().nodename)
        self._active_connections: Dict[str, asyncio.Transport] = {}
        self._rate_limiter = asyncio.Semaphore(CRA_PARAMS.rate_limit_per_second)

    async def start(self) -> None:
        """Start the QKD gateway server."""
        await self._key_exchange.initialize()
        
        self._server = await asyncio.start_server(
            self._handle_connection,
            host=self.host,
            port=self.port
        )
        
        logger.info(f"QuantumKeyDistributionGateway listening on {self.host}:{self.port}")
        
        # Start background rotation task
        asyncio.create_task(self._rotation_loop())
        
        async with self._server:
            await self._server.serve_forever()

    async def _handle_connection(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter) -> None:
        """
        Handle incoming QKD connection.
        FVE INV-004: Guaranteed socket cleanup via try/finally.
        """
        connection_id = str(uuid.uuid4())
        peer_addr = writer.get_extra_info('peername')
        logger.info(f"New connection {connection_id} from {peer_addr}")
        
        self._active_connections[connection_id] = writer
        
        try:
            # Rate limiting
            async with self._rate_limiter:
                await self._perform_key_exchange(reader, writer, connection_id)
        except asyncio.TimeoutError:
            logger.warning(f"Connection {connection_id} timed out")
        except Exception as e:
            logger.error(f"Connection {connection_id} error: {e}")
        finally:
            # FVE INV-004: Guaranteed socket cleanup
            try:
                writer.close()
                await writer.wait_closed()
            except Exception:
                pass
            finally:
                self._active_connections.pop(connection_id, None)
                logger.debug(f"Connection {connection_id} cleaned up")

    async def _perform_key_exchange(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter, connection_id: str) -> None:
        """
        Perform Kyber-1024 key exchange with client.
        """
        # Step 1: Send public key
        public_key = self._key_exchange.get_public_key()
        writer.write(struct.pack("!H", len(public_key)))
        writer.write(public_key)
        await writer.drain()
        
        # Step 2: Receive client's public key
        key_len_bytes = await reader.readexactly(2)
        client_key_len = struct.unpack("!H", key_len_bytes)[0]
        client_public_key = await reader.readexactly(client_key_len)
        
        # Step 3: Perform encapsulation
        shared_secret, ciphertext = await self._key_exchange.encapsulate(client_public_key)
        
        # Step 4: Send ciphertext to client
        writer.write(struct.pack("!H", len(ciphertext)))
        writer.write(ciphertext)
        await writer.drain()
        
        # Step 5: Store shared secret in rotation manager
        secret_id = f"secret_{connection_id}_{int(time.time())}"
        await self._rotation_manager.add_secret(secret_id, shared_secret)
        
        # Step 6: Propose EDSMA transaction for PBFT commit
        transaction = EDSMATransaction(
            transaction_type=EDSMATransactionType.KEY_ROTATION_POLICY,
            payload={
                "connection_id": connection_id,
                "secret_id": secret_id,
                "rotation_ttl": CRA_PARAMS.key_rotation_ttl_seconds
            }
        )
        await self._pbft_node.propose_transaction(transaction)
        
        logger.info(f"Key exchange completed for {connection_id}")

    async def _rotation_loop(self) -> None:
        """
        Background task for periodic key rotation.
        """
        while True:
            await asyncio.sleep(CRA_PARAMS.key_rotation_ttl_seconds)
            rotated = await self._rotation_manager.rotate_expired()
            if rotated > 0:
                logger.info(f"Rotated {rotated} expired secrets")
            
            # Log rotation stats
            stats = self._rotation_manager.get_stats()
            logger.debug(f"Rotation stats: {stats}")

    async def shutdown(self) -> None:
        """
        Graceful shutdown with FVE INV-004 cleanup.
        """
        logger.info("Shutting down QuantumKeyDistributionGateway")
        
        # Close all active connections
        for conn_id, writer in list(self._active_connections.items()):
            try:
                writer.close()
                await writer.wait_closed()
            except Exception:
                pass
        
        # Cleanup cryptographic material
        self._key_exchange.cleanup()
        
        # Close server
        if self._server:
            self._server.close()
            await self._server.wait_closed()
        
        logger.info("QuantumKeyDistributionGateway shutdown complete")


